/**
 * 解析 - Wallos（订阅到期提醒）
 */

// ======================= 可配置图标 =======================
// Wallos 订阅到期提醒图标
const WALLOS_ICON = "https://cdn.jsdelivr.net/gh/selfhst/icons/png/wallos.png";
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
let testMode = false;
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    return payload;
};

const { kind, payload } = $input.first().json;
testMode = payload.__test === true;
if (kind !== "wallos") return [];

const many = payload.subscriptionsinfo || {};
const one = payload.subscriptioninfo || {};
const pick = (key) => {
    const a = str(one[key]).trim();
    if (a) return a;
    return str(many[key]).trim();
};

const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const amountText = [pick("price"), pick("currency")].filter(Boolean).join(" ");
const priceText = [pick("payer"), amountText].filter(Boolean).join(" ➡️ ") || DASH;
const days = pick("days");
const title = `💳 ${val(pick("name"))} 订阅即将到期！！！`;
const body =
    `【订阅价格】${priceText}\n` +
    `【订阅时限】${days ? `${days} 天` : DASH}\n` +
    `【订阅类别】${val(pick("category"))}\n` +
    `【订阅日期】${val(pick("date"))}\n` +
    `【订阅备注】${val(pick("notes"))}\n\n` +
    `🔗订阅链接🔗 ${val(pick("url"))}`;

return [
    {
        json: {
            bark: bark("Wallos", title, body, { icon: WALLOS_ICON }),
            source: "Wallos"
        }
    }
];
